contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint balBefore = address(c).balance;

        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint balAfterFirst = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint balAfterSecond = address(c).balance;

        bool firstCompletedTransferredAll = (!firstReverted) && (balBefore - balAfterFirst == amount);
        bool firstRevertedKeptCredit = firstReverted && (balAfterFirst == balBefore);

        assert((firstCompletedTransferredAll && balAfterSecond == balAfterFirst) || (firstRevertedKeptCredit && balAfterSecond == balBefore - amount));
    }

    receive() external payable {}
}

