pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.deposit{value: amount}() {} catch { return; }
        uint balBefore = address(c).balance;
        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint balAfterFirst = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        uint balAfterSecond = address(c).balance;
        bool firstCompletedTransferredAll = (!firstReverted) && (balBefore - balAfterFirst == amount);
        bool firstRevertedKeptCredit = firstReverted && (balAfterFirst == balBefore);
        assertTrue((firstCompletedTransferredAll && balAfterSecond == balAfterFirst) || (firstRevertedKeptCredit && balAfterSecond == balBefore - amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
